<?php
namespace App\Http\Controllers;
use App\Models\PaymentInvoice; use App\Services\Payments\LocalPaymentService; use Illuminate\Http\Request;
class LocalPaymentController extends Controller { public function show(PaymentInvoice $invoice){$this->authorize('view',$invoice);abort_if($invoice->legacy_invoice_id!==null||(int)$invoice->getKey()===837,404);return view('payments.local',compact('invoice'));} public function create(Request $request,PaymentInvoice $invoice,LocalPaymentService $service){$this->authorize('view',$invoice);$t=$service->create($invoice,(int)$request->user()->getKey());return response()->json(['order_id'=>$t->order_id,'status'=>$t->transaction_status]);} public function callback(Request $request,LocalPaymentService $service){abort_unless($request->user()?->can('foundation.update'),403);$d=$request->validate(['order_id'=>['required','string'],'status'=>['required','string'],'transaction_id'=>['nullable','string']]);return response()->json($service->callback($d['order_id'],$d['status'],$d['transaction_id']??null));} }
